code.cpp:
class Solution {
public:
    int secondsToRemoveOccurrences(string s) {
        int cnt0 = 0, dp = 0;
        for (char c : s) {
            if (c == '0') {
                cnt0++;
            } else if (cnt0 > 0) {
                dp = max(dp + 1, cnt0);
            }
        }
        return dp;
    }
};
